      <ul role="menu">
        <li role="none" class="p-2" v-for="(link, index) in links" :key="index">
          <button role="menuitem" :aria-expanded="!!link.children && link.open" :aria-haspopup="!!link.children"
            :class="{ active: link.active }" @click="setActive(index)"
            class="flex items-center w-full text-left py-3 pl-4 hover:bg-gray-100 dark:hover:bg-white/10 text-black dark:text-white">
            <Icon :icon="link.icon" class="h-5 w-5" />
            <span class="ml-2">{{ link.name }}</span>
            <span v-if="link.children" class="ml-auto dropdown-icon">
              <Icon :icon="link.open ? 'line-md:chevron-down ' : 'line-md:chevron-right'" />
            </span>
          </button>

<ul v-if="link.children && link.open" class="ml-4 pl-4 border-l border-gray-200 dark:border-white/10">
  <li
    v-for="(child, childIndex) in link.children"
    :key="childIndex"
    class="my-2"
  >
    <router-link
      :to="child.to"
      :class="[
        'block py-2 px-3 rounded-md hover:bg-gray-100 dark:hover:bg-white/10 text-black dark:text-white',
        { 'submenu-active': child.active }
      ]"
      @click.prevent="setActive(index, childIndex)"
    >
      {{ child.name }}
    </router-link>
  </li>
</ul>

        </li>
      </ul>
    </nav>
  </aside>
</template>
<script setup>
import { ref } from "vue";
import { useRouter } from "vue-router";

const router = useRouter();

const links = ref([
  {
    name: "Dashboard",
    icon: "line-md:home",
    to: "/dashboard",
    active: true,
    open: false,
  },
  {
    name: "Pengguna",
    icon: "line-md:account",
    to: "#",
    active: false,
    open: false,
  },
  {
    name: "Template Dokumen",
    icon: "line-md:document-list",
    to: "#",
    active: false,
    open: false,
  },
  {
    name: "Laporan",
    icon: "mdi:folder-outline",
    active: false,
    open: true,
    children: [
      { name: "Rangking Sekolah", to: "/dashboard/rangking", active: false },
      { name: "Menu Revitalisasi", to: "#", active: false },
      { name: "Verifikasi", to: "#", active: false },
    ],
  },
]);

const setActive = (index, childIndex = null) => {
  const link = links.value[index];

  if (childIndex === null) {
    // click parent
    if (link.children) {
      link.open = !link.open;
    }
    if (link.to && link.to !== "#") {
      router.push(link.to);
    }

    // set active parent only, clear all children
    links.value.forEach((l, i) => {
      l.active = i === index;
      if (l.children) {
        l.children.forEach((c) => (c.active = false));
      }
    });
  } else {
    // click child
    const child = link.children[childIndex];

    if (child.to && child.to !== "#") {
      router.push(child.to);
    }

    // make parent section active and highlight selected child
    links.value.forEach((l, i) => {
      l.active = i === index;
      if (l.children) {
        l.children.forEach((c, ci) => {
          c.active = i === index && ci === childIndex;
        });
      }
    });

    // ensure folder stays open when a child is active
    link.open = true;
  }
};
</script>

<style>
button:active {
  background-color: rgb(11, 238, 113) !important;
  color: #111827 !important;
}

/* item menu aktif (light mode) */
.menu .active {
  background-color: rgb(39, 255, 136);
  color: #111827;
  font-weight: 600;
}

/* item menu aktif saat dark mode */
.dark .menu .active {
  background-color: rgba(255, 255, 255, 0.08);
  color: #f9fafb;
}
</style>
